package io.github.campione01.mineclientbridge;
import com.google.gson.*;
import java.nio.file.*;
import java.util.*;
import java.util.jar.JarFile;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;

/** Offline DTO/production-codec/bounds and pinned hook-order checks; all geometry/events synthetic. */
public final class RecoveryDamageDiagnosticChecks {
    static int checks;
    static void check(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
    static JsonObject nativeState(){JsonObject n=new JsonObject();n.addProperty("enabled",true);n.addProperty("owner_id","11111111-1111-4111-8111-111111111111");for(String k:List.of("active_id","profile","state"))n.add(k,JsonNull.INSTANCE);n.addProperty("applied_count",0);n.addProperty("next_generation",95);n.addProperty("entry_count",94);n.addProperty("unknown_lock",false);return n;}
    static JsonObject pos(){JsonObject p=new JsonObject();p.addProperty("x",-635.0);p.addProperty("y",60.0);p.addProperty("z",17.2);return p;}
    static JsonObject server(long nano){JsonObject s=new JsonObject();s.addProperty("nano_time",nano);s.addProperty("server_tick",1);s.addProperty("game_time",12345);s.addProperty("player_uuid","22222222-2222-4222-8222-222222222222");s.addProperty("health",20.0);s.add("position",pos());return s;}
    static JsonObject client(int tick,boolean nonzero){JsonObject c=server(100+tick);c.remove("server_tick");c.remove("game_time");c.addProperty("client_tick",tick);JsonObject i=new JsonObject();i.addProperty("forward",nonzero?1.0:0.0);i.addProperty("strafe",0.0);i.addProperty("jump",false);c.add("input",i);c.add("native",nativeState());return c;}
    static JsonObject damage(long now){JsonObject d=server(now);d.remove("health");d.addProperty("health_after",18.0);d.addProperty("original_damage",2.0);d.addProperty("new_damage",2.0);d.addProperty("blocked_damage",0.0);d.addProperty("source_key","minecraft:mob_attack");JsonObject e=pos();e.addProperty("type","minecraft:zombified_piglin");e.addProperty("uuid","33333333-3333-4333-8333-333333333333");d.add("direct",e);d.add("causing",e.deepCopy());d.addProperty("client_snapshot_nanos",101);d.add("native_snapshot",nativeState());return d;}
    static ClassNode clazz(JarFile jar,String name)throws Exception{try(var in=jar.getInputStream(jar.getJarEntry(name+".class"))){ClassNode c=new ClassNode();new ClassReader(in).accept(c,0);return c;}}
    static MethodNode method(ClassNode c,String name){return c.methods.stream().filter(m->m.name.equals(name)).findFirst().orElseThrow();}
    static int call(MethodNode m,String name){int i=0;for(var n:m.instructions){if(n instanceof MethodInsnNode x&&x.name.equals(name))return i;i++;}return -1;}
    public static void main(String[] args)throws Exception{
        Path out=Path.of(args[0]);Files.createDirectories(out);var disabled=new RecoveryDamageDiagnostics.Recorder(false);disabled.server(server(100),100);check(!disabled.snapshot(101).get("window_started").getAsBoolean(),"disabled_does_not_start");
        var r=new RecoveryDamageDiagnostics.Recorder(true);Files.write(out.resolve("before-world.json"),RecoveryDamageDiagnostics.encode(r.snapshot(99)));r.server(server(100),100);r.client(client(1,false),101);Files.write(out.resolve("first-world.json"),RecoveryDamageDiagnostics.encode(r.snapshot(102)));
        for(int i=2;i<=500;i++)r.client(client(i,i==211),100+i);var before=r.snapshot(601);check(before.get("client_total").getAsLong()==500,"counts_every_sampling_point");check(before.get("client_nonzero_count").getAsLong()==1&&before.get("first_nonzero_tick").getAsInt()==211,"middle_nonzero_not_hidden_by_sampling");check(before.getAsJsonObject("client_first").get("client_tick").getAsInt()==1&&before.getAsJsonObject("client_latest").get("client_tick").getAsInt()==500,"first_latest_preserved");
        var early=new RecoveryDamageDiagnostics.Recorder(true);JsonObject ed=damage(100);for(String k:List.of("source_key","direct","causing","client_snapshot_nanos","native_snapshot"))ed.add(k,JsonNull.INSTANCE);early.damage(ed,100);var es=early.snapshot(101);check(es.get("window_started").getAsBoolean()&&es.get("client_first").isJsonNull()&&es.get("damage_total").getAsInt()==1,"early_server_damage_not_gated_on_client");Files.write(out.resolve("damage-before-client.json"),RecoveryDamageDiagnostics.encode(es));
        r.damage(damage(700),700);Files.write(out.resolve("first-damage.json"),RecoveryDamageDiagnostics.encode(r.snapshot(701)));
        for(int i=501;i<601;i++)r.client(client(i,(i&1)==0),100+i);
        for(int i=0;i<40;i++)r.damage(damage(800+i),800+i);var full=r.snapshot(900);check(full.get("damage_total").getAsLong()==41&&full.get("damage_dropped").getAsLong()==9&&full.getAsJsonArray("damage_events").size()==32,"damage_cap_preserves_first_and_reports_drop");check(full.get("client_dropped").getAsLong()>0&&full.getAsJsonArray("client_samples").size()==32,"client_changes_ring_bounded");
        check(full.getAsJsonArray("damage_events").get(0).getAsJsonObject().get("sequence").getAsLong()==1,"first_damage_retained");
        r.client(client(999,true),100+RecoveryDamageDiagnostics.WINDOW_NANOS);r.damage(damage(999),100+RecoveryDamageDiagnostics.WINDOW_NANOS);var ended=r.snapshot(100+RecoveryDamageDiagnostics.WINDOW_NANOS);check(ended.get("window_closed").getAsBoolean()&&ended.get("client_total").equals(full.get("client_total"))&&ended.get("damage_total").equals(full.get("damage_total")),"absolute_window_no_extension");
        r.server(server(50),50);check(r.snapshot(50).get("window_closed").getAsBoolean(),"clock_reversal_fail_closed");r.error();check(r.snapshot(901).get("capture_errors").getAsLong()==1,"capture_failure_visible");
        full.getAsJsonObject("client_first").addProperty("health",0);check(r.snapshot(901).getAsJsonObject("client_first").get("health").getAsDouble()==20,"get_snapshot_does_not_expose_mutable_store");
        JsonObject worst=r.snapshot(902);for(JsonElement element:worst.getAsJsonArray("damage_events")){JsonObject d=element.getAsJsonObject();d.addProperty("source_key","s".repeat(128));for(String k:List.of("direct","causing"))d.getAsJsonObject(k).addProperty("type","t".repeat(128));}byte[] encoded=RecoveryDamageDiagnostics.encode(worst);check(encoded.length<=65536,"bounded_idle_identifier_payload_under64KiB");Files.write(out.resolve("bounded-full-synthetic.json"),encoded);Files.write(out.resolve("window-closed.json"),RecoveryDamageDiagnostics.encode(ended));
        try(var jar=new JarFile(args[1])){var player=method(clazz(jar,"net/minecraft/world/entity/player/Player"),"tick");check(call(player,"tick")>=0&&call(player,"firePlayerTickPost")>call(player,"tick"),"pinned_playerpost_after_living_tick");var mc=method(clazz(jar,"net/minecraft/client/Minecraft"),"tick");check(call(mc,"tickEntities")>=0&&call(mc,"fireClientTickPost")>call(mc,"tickEntities"),"pinned_clientpost_cleanup_after_entitytick");}
        try(var in=RecoveryDamageDiagnostics.class.getResourceAsStream("RecoveryDamageDiagnostics.class")){ClassNode c=new ClassNode();new ClassReader(in).accept(c,0);for(var m:c.methods)for(var n:m.instructions)if(n instanceof MethodInsnNode x){check(!Set.of("setCanceled","setNewDamage","hurt","attack","setDeltaMovement","setPos","setHealth","execute","send","startDestroyBlock","continueDestroyBlock").contains(x.name),"no_mutating_or_scheduler_calls_in_diag_"+x.name);}}
        JsonObject extreme=worst.deepCopy();List<JsonObject> ns=new ArrayList<>();for(String k:List.of("client_first","client_latest"))ns.add(extreme.getAsJsonObject(k).getAsJsonObject("native"));for(JsonElement e:extreme.getAsJsonArray("client_samples"))ns.add(e.getAsJsonObject().getAsJsonObject("native"));for(JsonElement e:extreme.getAsJsonArray("damage_events"))ns.add(e.getAsJsonObject().getAsJsonObject("native_snapshot"));for(JsonObject n:ns){n.addProperty("owner_id","o".repeat(128));n.addProperty("active_id","a".repeat(128));n.addProperty("profile","recovery_interaction_v2");n.addProperty("state","DISPATCH_FENCED");n.addProperty("applied_count",32);n.addProperty("next_generation",9007199254740991L);n.addProperty("entry_count",256);}byte[] extremeBytes=RecoveryDamageDiagnostics.encode(extreme);check(extremeBytes.length<131072,"native_protocol_max_identity_budget_under128KiB");Files.write(out.resolve("budget-extreme-synthetic.json"),extremeBytes);
        JsonObject over=new JsonObject();over.addProperty("oversized_test","x".repeat(131073));try{RecoveryDamageDiagnostics.encode(over);throw new AssertionError("diag_budget_not_enforced");}catch(IllegalArgumentException expected){check(expected.getMessage().equals("diagnostic_response_too_large"),"diagnostic_only_encode_budget_enforced");}
        JsonObject meta=new JsonObject();meta.addProperty("fixture_origin","synthetic input through production Recorder.snapshot and RecoveryShortInputCodec.encode; not live gameplay evidence");meta.addProperty("largest_fixture_bytes",extremeBytes.length);meta.addProperty("sampling_boundary","PlayerTick.Post after LivingEntity.tick and before ClientTick.Post cleanup; does not prove every external input writer");Files.write(out.resolve("ORIGIN.json"),RecoveryDamageDiagnostics.encode(meta));
        System.out.println("RecoveryDamageDiagnosticChecks PASS assertions="+checks+" largest_fixture_bytes="+extremeBytes.length);
    }
}
